import{c as s,a1 as r,U as i,j as o,g as a,n,p as l}from"./chunks/framework.h4W4t1IS.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Programmation Objet II","tagline":"Notes de cours - 420-W30-SF"},"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),d={name:"index.md"},c={class:"home-content"};function u(p,e,m,g,v,b){const t=r("ActiveFlagsBox");return i(),o("div",null,[a("div",c,[e[0]||(e[0]=n('<h2 id="a-propos-du-cours" tabindex="-1">À propos du cours <a class="header-anchor" href="#a-propos-du-cours" aria-label="Permalink to &quot;À propos du cours&quot;">​</a></h2><p>Ce cours est le deuxième de trois cours porteurs de la compétence <strong>00Q6 - Exploiter les principes de la programmation orientée objet</strong>, introduite en session 2 dans le cours <em>Programmation objet I</em> et aussi développée dans le cours <em>Algorithmique avancée</em>. Il approfondit les concepts de la programmation objet vus dans le cours précédent en plus d&#39;introduire les <a href="/420-w30-sf-po2/lexique.html#patrons-de-conception" class="lexicon-link" title="Solutions réutilisables à des problèmes courants de conception logicielle, fournissant des modèles éprouvés pour structurer et organiser le code.">patrons de conception</a> et l&#39;utilisation d&#39;outils de contrôle de source.</p><p>Il est le premier de deux cours porteurs de la compétence <strong>00Q8 - Effectuer des opérations de prévention en matière de sécurité de l’information</strong>, approfondie dans le cours <em>Cybersécurité</em>.</p><p>L&#39;accent est mis sur les <strong>bonnes pratiques de développement</strong> : compromis en lien avec la programmation objet, la maintenabilité, la lisibilité et la testabilité du code sont aux coeurs du cours de <em>Programmation objet II</em>.</p><details class="details custom-block"><summary>Place dans le programme et préalables</summary><p><strong>Préalables</strong></p><ul><li>PA : 420-W20-SF - Programmation objet I</li></ul><p><strong>Ce cours est préalable à</strong></p><ul><li>420-W31-SF - Algorithmique avancée (préalable concomitant)</li><li>420-W41-SF - Développement de services Web</li><li>420-W42-SF - Programmation de jeux vidéo I</li><li>420-W49-SF - Bases de données II : SQL avancé et requêtes objets</li><li>420-W50-SF - Développement mobile et objets connectés</li><li>420-W54-SF - Innovation et veille technologique</li></ul><p><strong>Contexte de réalisation (compétence 00Q6)</strong></p><p>Les compétences seront exercées à partir d&#39;un problème, à l&#39;aide de règles de nomenclature et de codage, dans des contextes représentatifs du seuil d&#39;entrée sur le marché du travail, l&#39;application de mesures de sécurité reconnues.</p></details><h2 id="utilisation-de-l-intelligence-artificielle" tabindex="-1">Utilisation de l&#39;intelligence artificielle <a class="header-anchor" href="#utilisation-de-l-intelligence-artificielle" aria-label="Permalink to &quot;Utilisation de l&#39;intelligence artificielle&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Outils d&#39;intelligence artificielle générative</p><p>Dans ce cours, les habiletés visées exigent que l’étudiant ou l’étudiante réalise de manière autonome les tâches visées par les évaluations, sans recourir aux outils d’IAg. C’est pourquoi leur utilisation sera interdite pour toutes les évaluations.</p><table tabindex="0"><thead><tr><th>Tâche</th><th>Raisonnement pédagogique</th></tr></thead><tbody><tr><td>À des fins de résumé de textes</td><td>Afin d’éviter les interprétations inexactes faites par les outils d’IAg. <br> Afin de te permettre de développer une aisance face à l’ambiguïté.</td></tr><tr><td>Pour planifier une tâche Afin d’être en mesure de planifier la réalisation de façon autonome.</td><td>Un plan de réalisation est proposé dans chaque récit utilisateur.</td></tr><tr><td>Générer du code</td><td>Afin de développer une capacité pour la production de code et assurer ta compréhension du travail produit.</td></tr><tr><td>Générer des tests</td><td>Afin de développer une capacité pour la production de tests et assurer ta compréhension du travail produit.</td></tr><tr><td>Générer des diagrammes techniques</td><td>Afin de développer une vue d’ensemble sur le code à produire.<br>Inclus sans s’y limiter, diagrammes de classe, de séquence et d’architecture</td></tr><tr><td>Générer un plan de tests</td><td>Afin de développer ta capacité à identifier les cas de test pertinents (chemins normaux, limites et d&#39;erreur) en lien avec les bonnes pratiques vues dans le cours.</td></tr></tbody></table><p><strong>Pour toute autre tâche absente de la liste ci-dessus, validez avec votre professeur pour éviter les mauvaises surprises.</strong></p></div><details class="details custom-block"><summary>Conception de ce site</summary><p>Les notes de cours ont été rédigées avec l&#39;assistance d&#39;outils d&#39;intelligence artificielle générative. Tout le contenu a été révisé et validé par votre professeur.</p></details>',8)),l(t)])])}const x=s(d,[["render",u]]);export{h as __pageData,x as default};
